#!/usr/bin/env bash
# Doc développeur : la partie « La corbeille ».
# Prérequis : apply-fix-corbeille.sh.
# Usage (racine du repo) : bash apply-docs-corbeille.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/index.mdx" 2>/dev/null | grep -qF "Jeter, retrouver, effacer"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "askedByWrapper" "packages/backend/src/modules/trash/services/purge.service.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-corbeille.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/finder/trois-finders-en-un.mdx" "apps/web/content/docs/dev/envois/les-formulaires-de-lot.mdx" "apps/web/content/docs/dev/index.mdx")
CREATED=("apps/web/content/docs/dev/corbeille/jeter-retrouver-effacer.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/corbeille" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "Jeter, retrouver, effacer" "apps/web/content/docs/dev/index.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/corbeille"
